import { readFileSync, readdirSync, rmSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
export const SPEC_DIR = join(REPO_ROOT, 'docs', 'spec');
export const SEED_DIR = join(SPEC_DIR, 'seed', 'aa');
export const GENERATED_DIR = join(REPO_ROOT, 'tier2-logic', 'spec', 'src', 'generated');

const HEADER = [
  '// DO NOT EDIT. Generated by tools/gen-types from docs/spec (read-only).',
  '// Regenerate with `pnpm gen:types`; CI regenerates and fails on any diff.',
  '',
].join('\n');

export function readJson(path: string): unknown {
  return JSON.parse(readFileSync(path, 'utf8')) as unknown;
}

/* ---------- shape inference: observe every instance, emit a zod expression ---------- */

interface ShapeNode {
  string?: true;
  number?: true;
  boolean?: true;
  null?: true;
  array?: { item: ShapeNode | undefined };
  object?: { count: number; fields: Map<string, { node: ShapeNode; seen: number }> };
}

function observe(node: ShapeNode, value: unknown): void {
  if (value === null) {
    node.null = true;
  } else if (typeof value === 'string') {
    node.string = true;
  } else if (typeof value === 'number') {
    node.number = true;
  } else if (typeof value === 'boolean') {
    node.boolean = true;
  } else if (Array.isArray(value)) {
    node.array ??= { item: undefined };
    for (const el of value) {
      node.array.item ??= {};
      observe(node.array.item, el);
    }
  } else if (typeof value === 'object') {
    node.object ??= { count: 0, fields: new Map() };
    node.object.count += 1;
    for (const [key, v] of Object.entries(value as Record<string, unknown>)) {
      const field = node.object.fields.get(key) ?? { node: {}, seen: 0 };
      field.seen += 1;
      observe(field.node, v);
      node.object.fields.set(key, field);
    }
  }
}

const IDENT = /^[A-Za-z_$][\w$]*$/;

function emit(node: ShapeNode, indent: number): string {
  const parts: string[] = [];
  if (node.string) parts.push('z.string()');
  if (node.number) parts.push('z.number()');
  if (node.boolean) parts.push('z.boolean()');
  if (node.null) parts.push('z.null()');
  if (node.array) {
    parts.push(`z.array(${node.array.item ? emit(node.array.item, indent) : 'z.unknown()'})`);
  }
  if (node.object) {
    const { count, fields } = node.object;
    if (fields.size === 0) {
      parts.push('z.object({})');
    } else {
      const pad = '  '.repeat(indent + 1);
      const lines = [...fields.entries()].map(([key, field]) => {
        const name = IDENT.test(key) ? key : JSON.stringify(key);
        const optional = field.seen < count ? '.optional()' : '';
        return `${pad}${name}: ${emit(field.node, indent + 1)}${optional},`;
      });
      parts.push(`z.object({\n${lines.join('\n')}\n${'  '.repeat(indent)}})`);
    }
  }
  if (parts.length === 0) return 'z.unknown()';
  return parts.length === 1 ? (parts[0] as string) : `z.union([${parts.join(', ')}])`;
}

function schemaFor(name: string, value: unknown): string {
  const root: ShapeNode = {};
  observe(root, value);
  return [
    `export const ${name}Schema = ${emit(root, 0)};`,
    `export type ${name} = z.infer<typeof ${name}Schema>;`,
    '',
  ].join('\n');
}

function fileFor(name: string, body: string): string {
  return `${HEADER}\nimport { z } from 'zod';\n\n${body}`;
}

/* ---------- id unions ---------- */

function uniqueIds(label: string, values: unknown[], pick: (v: unknown) => string): string[] {
  const out = values.map(pick);
  const seen = new Set<string>();
  for (const id of out) {
    if (seen.has(id)) throw new Error(`gen-types: duplicate ${label} id "${id}"`);
    seen.add(id);
  }
  return out;
}

function idUnion(union: string, schemaName: string, label: string, list: string[]): string {
  const body = list.map((id) => `  ${JSON.stringify(id)},`).join('\n');
  return [
    `/** ${label}: ${list.length} ids, verbatim from the spec JSON. */`,
    `export const ${union} = [`,
    body,
    '] as const;',
    `export const ${schemaName} = z.enum(${union});`,
    `export type ${schemaName.replace(/Schema$/, '')} = z.infer<typeof ${schemaName}>;`,
    '',
  ].join('\n');
}

function idsFile(): string {
  const variables = readJson(join(SPEC_DIR, 'variables.json')) as { variables: unknown[] };
  const graph = readJson(join(SPEC_DIR, 'formula_graph.json')) as { nodes: unknown[]; dimensions: unknown[] };
  const solvers = readJson(join(SPEC_DIR, 'solvers.json')) as { problems: unknown[] };
  const schema = readJson(join(SPEC_DIR, 'schema.json')) as { validation_rules: unknown[] };
  const pickId = (v: unknown): string => (v as { id: string }).id;
  const body = [
    idUnion('VarIds', 'VarIdSchema', 'Variables (variables.json)', uniqueIds('VarId', variables.variables, pickId)),
    idUnion('NodeIds', 'NodeIdSchema', 'Formula nodes (formula_graph.json)', uniqueIds('NodeId', graph.nodes, pickId)),
    idUnion('DimIds', 'DimIdSchema', 'Dimensions (formula_graph.json)', uniqueIds('DimId', graph.dimensions, pickId)),
    idUnion('ProblemIds', 'ProblemIdSchema', 'Solver problems (solvers.json)', uniqueIds('ProblemId', solvers.problems, pickId)),
    idUnion('VRIds', 'VRIdSchema', 'Validation rules (schema.json)', uniqueIds('VRId', schema.validation_rules, pickId)),
  ].join('\n');
  return fileFor('ids', body);
}

/* ---------- whole-bundle generation ---------- */

const SPEC_INPUTS: Array<{ file: string; name: string; out: string }> = [
  { file: 'variables.json', name: 'Variables', out: 'variables' },
  { file: 'formula_graph.json', name: 'FormulaGraph', out: 'formula-graph' },
  { file: 'solvers.json', name: 'Solvers', out: 'solvers' },
  { file: 'excel_template.json', name: 'ExcelTemplate', out: 'excel-template' },
  { file: 'schema.json', name: 'DbSchema', out: 'db-schema' },
];

function pascal(s: string): string {
  return s
    .split(/[_-]/)
    .filter(Boolean)
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join('');
}

/** Returns every generated file as name -> source. Pure apart from reading the spec JSON. */
export function generateAll(): Map<string, string> {
  const files = new Map<string, string>();
  for (const input of SPEC_INPUTS) {
    const value = readJson(join(SPEC_DIR, input.file));
    files.set(`${input.out}.ts`, fileFor(input.name, schemaFor(input.name, value)));
  }
  for (const file of readdirSync(SEED_DIR).filter((f) => f.endsWith('.json')).sort()) {
    const base = file.replace(/\.json$/, '');
    const name = `SeedAa${pascal(base)}`;
    const value = readJson(join(SEED_DIR, file));
    files.set(`seed-aa-${base.replace(/_/g, '-')}.ts`, fileFor(name, schemaFor(name, value)));
  }
  files.set('ids.ts', idsFile());
  const exportsList = [...files.keys()].sort().map((f) => `export * from './${f.replace(/\.ts$/, '')}';`);
  files.set('index.ts', `${HEADER}\n${exportsList.join('\n')}\n`);
  return files;
}

/** Writes generated files, removing stale ones so the directory mirrors the generator exactly. */
export function writeAll(outDir: string = GENERATED_DIR): string[] {
  const files = generateAll();
  mkdirSync(outDir, { recursive: true });
  if (existsSync(outDir)) {
    for (const f of readdirSync(outDir)) {
      if (f.endsWith('.ts') && !files.has(f)) rmSync(join(outDir, f));
    }
  }
  for (const [file, source] of files) writeFileSync(join(outDir, file), source);
  return [...files.keys()].sort();
}
